import {openDialog,closeDialog} from './ui-core.mjs';
import{presets,task,evaluate,metrics}from './engine.mjs';
import {integrationsPage,bindIntegrations} from './integration-ui.mjs';
import {codingPage,bindCoding} from './coding-ui.mjs';
import {usagePage,bindUsage} from './usage-ui.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={running:'运行中',success:'已完成',stopped:'已熔断',approval:'待审批',failed:'失败'},acts={stop:'自动停止',degrade:'降级模型',approve:'人工确认'};
const iconPaths={coding:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',runs:'M3 12h4l3-8 4 16 3-8h4',alerts:'M12 3 2 21h20L12 3Z M12 9v5 M12 17h.01',cost:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',policies:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',integrations:'M8 3v5 M16 3v5 M5 8h14v4a7 7 0 0 1-14 0V8Z M12 19v3',deploy:'M4 4h16v6H4z M4 14h16v6H4z M7 7h.01 M7 17h.01',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M8 12l3 3 5-6',loop:'M4 10a8 8 0 0 1 14-4l3 3 M21 3v6h-6 M20 14a8 8 0 0 1-14 4l-3-3 M3 21v-6h6',retry:'M5 8a8 8 0 1 1-1 9 M5 3v5h5',swarm:'M12 3v7 M5 21v-7h14v7 M12 10v11 M9 3h6',success:'M5 12l4 4L19 6',wallet:'M3 5h17v15H3z M3 8h17 M15 12h6v5h-6z'};
const icon=k=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(iconPaths[k]||iconPaths.shield)+'"/></svg>';
const validPolicy=p=>p&&Number.isFinite(p.budget)&&p.budget>0&&['loop','retries','children'].every(k=>Number.isInteger(p[k])&&p[k]>0)&&p.loop>=2&&p.loop<=12&&Object.hasOwn(acts,p.action);
let saved;try{saved=JSON.parse(localStorage.getItem('ag-v1'));if(!saved||!Object.keys(presets).every(k=>validPolicy(saved.policies?.[k]))||!Array.isArray(saved.tasks)||!saved.tasks.every(t=>t&&typeof t.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(t.id)&&(t.budgetOverride==null||(Number.isFinite(t.budgetOverride)&&t.budgetOverride>0))&&Object.hasOwn(presets,t.policy)&&Object.hasOwn(labels,t.status)&&Number.isFinite(t.cost)&&t.cost>=0&&Array.isArray(t.events)&&Array.isArray(t.alerts)&&Array.isArray(t.childIds)))saved=null}catch{saved=null}
let policies=saved?.policies||structuredClone(presets),tasks=saved?.tasks||seed(),current='overview',timer=null,activeTask=null,toastTimer=null,storageWarning=false;
for(const k of Object.keys(presets))policies[k].name=presets[k].name;
for(const t of tasks){if(t.simulation&&(!['loop','retry','swarm','budget','normal'].includes(t.simulation.scenario)||!Number.isInteger(t.simulation.step))){delete t.simulation;t.status='stopped'}}
function seed(){return [['市场趋势研究','research','星河科技','竞品研究',7.42,'running'],['售后问题处理','support','青禾电商','智能客服',1.43,'success'],['社媒内容生成','content','青禾电商','内容生产',3.82,'success'],['行业数据采集','research','云帆数据','行业研究',3.64,'stopped'],['新品推广文案','content','星河科技','营销文案',2.15,'success'],['深度竞品分析','research','云帆数据','竞品研究',10.12,'approval']].map((d,i)=>{const t=task('AG-'+(1028-i),d[1],{name:d[0],customer:d[2],feature:d[3],cost:d[4],status:d[5]});if(i===3||i===5)t.alerts.push({id:'seed'+i,type:i===3?'loop':'budget',title:i===3?'重复调用循环':'任务预算触顶',detail:i===3?'search_web 使用相同参数重复调用 4 次':'累计 ¥10.12 / 预算 ¥10.00',action:i===3?'stop':'approve',at:new Date().toISOString()});return t})}
const nav=[['overview','◫','运行总览'],['runs','↗','任务追踪'],['alerts','◉','风险与审批'],['coding','⌁','编码工具'],['usage','▥','用量历史'],['cost','▥','成本分析'],['policies','☷','费用策略'],['integrations','⊞','接入中心'],['deploy','⌘','私有部署']];
function persist(){try{localStorage.setItem('ag-v1',JSON.stringify({policies,tasks}));return true}catch{if(!storageWarning){toast('浏览器存储不可用，当前修改仅在本次页面有效');storageWarning=true}return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function title(h,p,b=''){return '<div class="heading"><div><h1>'+h+'</h1><p>'+p+'</p></div><div class="actions">'+b+'</div></div>'}
function stat(l,v,f){return '<div class="card stat"><div class="label">'+l+'<span class="stat-icon">'+icon(l==='累计任务成本'?'wallet':l==='风险事件'?'alerts':l==='成功任务率'?'success':'cost')+'</span></div><div class="value">'+v+'</div><small>'+f+'</small></div>'}
function show(){const sideTitle=document.querySelector('.side-status strong'),sideNote=document.querySelector('.side-status small');if(sideTitle)sideTitle.textContent='演示环境';if(sideNote)sideNote.textContent='本地模拟运行 · 不产生 API 费用';const environment=document.querySelector('.environment');if(environment)environment.textContent='演示模式';current=location.hash.slice(1)||'overview';if(!nav.some(n=>n[0]===current))current='overview';$('#breadcrumb').textContent=nav.find(n=>n[0]===current)[2];$('#nav').innerHTML=nav.map(n=>'<a class="'+(n[0]===current?'active':'')+'" href="#'+n[0]+'" '+(n[0]===current?'aria-current="page"':'')+'><span class="nav-icon">'+icon(n[0])+'</span>'+n[2]+(n[0]==='alerts'?'<em>'+tasks.filter(t=>t.status==='approval').length+'</em>':'')+'</a>').join('');$('#app').innerHTML=render();bind()}
function health(){const running=tasks.filter(t=>t.status==='running').length,pending=tasks.filter(t=>t.status==='approval').length,stopped=tasks.filter(t=>t.status==='stopped').length;return '<section class="health-strip" aria-label="运行健康状态"><span class="health-icon">'+icon('shield')+'</span><div class="health-copy"><strong>'+ (pending?'有 '+pending+' 个任务等待你的决策':'费用与行为护栏已就绪')+'</strong><p>循环检测 · 重试限制 · 子智能体预算 · 人工审批</p></div><div class="health-metrics"><span><b>'+running+'</b>运行中</span><span><b>'+pending+'</b>待审批</span><span><b>'+stopped+'</b>已停止</span></div><a class="button" href="#alerts">处理风险 →</a></section>'}
function stats(){const m=metrics(tasks);return '<div class="stats">'+stat('累计任务成本','<span>¥</span>'+m.cost.toFixed(2),'包含已计费的失败调用')+stat('风险事件',tasks.flatMap(t=>t.alerts).length,'循环 / 重试 / 子智能体 / 预算')+stat('成功任务率',(m.rate*100).toFixed(1)+'<span>%</span>',m.success+' 成功 / '+m.completed+' 已结束任务')+stat('每个成功任务成本',m.unit===null?'—':'<span>¥</span>'+m.unit.toFixed(2),'全部成本 ÷ 成功任务数')+'</div>'}
const demoButton='<button class="button primary" data-demo>＋ 异常演练</button>',exportButton='<button class="button" data-export>↓ 导出运行数据</button>';
function render(){
if(current==='coding')return codingPage();
if(current==='usage')return usagePage();
if(current==='overview'){const all=tasks.flatMap(t=>t.alerts);return title('运行总览','查看任务状态、费用与需要处理的风险。',exportButton+demoButton)+stats()+table(false)+'<div class="grid secondary-grid"><section class="card"><div class="card-head"><div><h2>费用 / 预算</h2><small>最近 6 个任务 · 人民币</small></div></div>'+chart()+'</section><section class="card"><div class="card-head"><h2>异常检测记录</h2><a class="link" href="#alerts">全部记录 →</a></div>'+[['loop','重复调用','同一智能体 · 最近 12 次调用'],['retry','连续失败','成功调用后重新计数'],['swarm','子智能体超限','根任务累计唯一子节点']].map(([k,n,d])=>'<div class="rule-row"><span class="rule-icon">'+icon(k)+'</span><div><strong>'+n+'</strong><small>'+d+'</small></div><span class="count">'+all.filter(a=>a.type===k).length+'</span></div>').join('')+'</section></div>'}
if(current==='runs')return title('任务追踪','按任务、客户或状态筛选运行记录。',demoButton)+table(true);
if(current==='alerts')return title('风险与审批','查看触发证据，对超预算任务追加预算或终止运行。')+(tasks.flatMap(t=>t.alerts.map(a=>'<div class="card alert-card '+(t.status==='approval'?'':'is-resolved')+'"><span class="rule-icon">'+icon(a.type)+' </span><div><strong>'+esc(a.title)+'</strong><p>'+esc(a.detail)+'</p><small>'+esc(t.id)+' · '+esc(t.customer)+' · '+acts[a.action]+' · '+labels[t.status]+'</small></div><div class="actions">'+(t.status==='approval'?'<button class="button primary" data-review="'+t.id+'">审批</button>':'')+'<button class="button" data-detail="'+t.id+'">查看轨迹 →</button></div></div>')).join('')||'<div class="card empty">当前没有风险事件</div>');
if(current==='cost'){const groups={};tasks.forEach(t=>(groups[JSON.stringify([t.customer,t.feature])]??=[]).push(t));return title('成本与业务结果','将失败和重试成本纳入核算，衡量真实的成功任务成本。',exportButton)+stats()+'<div class="card table-wrap"><table><thead><tr><th>客户 / 产品功能</th><th>总成本</th><th>成功 / 已结束</th><th>成功率</th><th>每次成功成本</th></tr></thead><tbody>'+Object.entries(groups).map(([k,ts])=>{const m=metrics(ts);return '<tr><td>'+esc(JSON.parse(k).join(' / '))+'</td><td>¥'+m.cost.toFixed(2)+'</td><td>'+m.success+' / '+m.completed+'</td><td>'+(m.rate*100).toFixed(0)+'%</td><td>'+(m.unit===null?'—':'¥'+m.unit.toFixed(2))+'</td></tr>'}).join('')+'</tbody></table></div><div class="note">每次成功成本包含该客户与功能下全部任务费用。待审批和运行中任务暂不进入成功率分母。</div>'}
if(current==='policies')return title('预设费用策略','此页配置本地演练策略；真实编码任务请在“编码工具”创建连接时配置。')+'<div class="cards3">'+Object.entries(policies).map(([k,p],i)=>'<form class="card policy" data-policy="'+k+'"><span class="rule-icon">'+icon(['shield','runs','policies'][i])+'</span><h2>'+p.name+'</h2><p>'+['低延迟响应，严格限制重复调用。','支持深度检索，超限后由人工判断。','批量内容生成，优先降级控制成本。'][i]+'</p>'+[['budget','单任务预算（元）',.01],['loop','重复调用阈值（12 次窗口）',2],['retries','连续失败上限',1],['children','累计子智能体上限',1]].map(([n,l,min])=>'<label>'+l+'</label><input name="'+n+'" type="number" min="'+min+'" '+(n==='loop'?'max="12"':'')+' step="'+(n==='budget'?'.01':'1')+'" required value="'+p[n]+'">').join('')+'<label>触发后执行</label><select name="action">'+Object.entries(acts).map(([v,n])=>'<option value="'+v+'" '+(p.action===v?'selected':'')+'>'+n+'</option>').join('')+'</select><button class="button primary">保存策略</button></form>').join('')+'</div><div class="note">降级在下一次调用生效；重复触发会升级为停止。预算耗尽后，降级也不能继续消耗，需要追加预算。循环检测采用可解释的启发式规则，需按业务调节阈值。</div>';
if(current==='integrations')return integrationsPage();
if(current==='deploy')return title('部署在你自己的基础设施','前端资源随包提供，支持在国内服务器运行服务。')+'<div class="grid"><section class="card policy"><span class="badge">Node.js 20.19 / SQLite / Docker</span><h2>从演示到真实调用</h2><p>浏览器支持演练；自部署服务提供 SQLite 用量账本、预算预留和模型代理。</p><pre>docker build -t agentguard .\ndocker run --env-file .env -p 8080:8080 \\\n  -v agentguard-data:/app/data agentguard</pre><a class="button" href="DEPLOY.md" download>↓ 下载部署说明</a> <a class="button" href="agentguard-source.tar.gz" download>↓ 下载完整源码</a><div class="note">当前使用 SQLite 事务账本，单进程运行。多副本部署仍需集中账本与团队认证。</div></section><section class="card policy"><h2>部署检查清单</h2>'+['配置 ADMIN_KEY 与 INGEST_KEY','设置供应商地址、模型 ID 和密钥','填写模型输入输出价格（人民币）','配置备用模型与费用策略','配置飞书 / 企业微信 Webhook','验证停止、降级与审批分支'].map((x,i)=>'<label style="display:flex;gap:10px"><input data-check="'+i+'" style="width:auto" type="checkbox">'+x+'</label>').join('')+'<div class="note">当前托管页面为演示。检查项勾选不代表已连接服务。</div></section></div>';
}
function chart(){const ts=tasks.slice(0,6),max=Math.max(12,...ts.map(t=>Math.max(t.cost,t.budgetOverride||policies[t.policy].budget))),w=520/ts.length;return '<div class="chart"><svg viewBox="0 0 600 180" role="img" aria-label="最近任务成本与预算对比">'+[0,1,2,3].map(i=>'<line x1="42" x2="585" y1="'+(15+i*42)+'" y2="'+(15+i*42)+'" stroke="#edf1eb" stroke-dasharray="3 4"/><text x="0" y="'+(19+i*42)+'" fill="#99a89a" font-size="9">¥'+(max*(1-i/3)).toFixed(0)+'</text>').join('')+ts.map((t,i)=>'<g><title>'+esc(t.name||t.id)+'：成本 ¥'+t.cost.toFixed(2)+' / 预算 ¥'+(t.budgetOverride||policies[t.policy].budget).toFixed(2)+'</title><rect x="'+(55+i*w)+'" y="'+(141-t.cost/max*126)+'" width="23" height="'+(t.cost/max*126)+'" fill="#647da5" rx="3"/><rect x="'+(80+i*w)+'" y="'+(141-(t.budgetOverride||policies[t.policy].budget)/max*126)+'" width="15" height="'+((t.budgetOverride||policies[t.policy].budget)/max*126)+'" fill="#c5cbd4" rx="3"/><text x="'+(55+i*w)+'" y="164" fill="#86958a" font-size="9">'+esc(t.id.slice(-4))+'</text></g>').join('')+'</svg><div class="legend"><span><i></i>累计成本</span><span><i class="orange"></i>任务预算</span></div></div>'}
function table(filters){return '<section class="card"><div class="card-head"><h2>'+ (filters?'全部运行任务':'最近任务')+'</h2>'+(filters?'<div class="filters"><input id="search" placeholder="搜索任务、客户…" aria-label="搜索任务"><select id="status" aria-label="筛选状态"><option value="">所有状态</option>'+Object.entries(labels).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></div>':'<a class="link" href="#runs">查看全部 →</a>')+'</div><div class="table-wrap"><table><thead><tr><th>任务 / ID</th><th>客户 / 功能</th><th>策略</th><th>累计成本 / 预算</th><th>状态</th><th></th></tr></thead><tbody id="rows">'+rows(tasks)+'</tbody></table></div></section>'}
function rows(ts){return ts.map(t=>'<tr><td><div class="task-name"><span class="task-glyph">'+icon(t.policy==='research'?'runs':t.policy==='support'?'shield':'policies')+'</span><div><strong>'+esc(t.name||t.id)+'</strong><small>'+esc(t.id)+'</small></div></div></td><td>'+esc(t.customer)+'<small>'+esc(t.feature)+'</small></td><td>'+esc(policies[t.policy].name)+'<small>'+esc(t.model)+'</small></td><td>¥'+t.cost.toFixed(2)+' <span style="color:#a6b1a8">/ '+(t.budgetOverride||policies[t.policy].budget).toFixed(2)+'</span><div class="meter"><span class="'+(t.cost/(t.budgetOverride||policies[t.policy].budget)>=1?'over':t.cost/(t.budgetOverride||policies[t.policy].budget)>.8?'high':'')+'" style="width:'+Math.min(100,t.cost/(t.budgetOverride||policies[t.policy].budget)*100)+'%"></span></div></td><td><span class="badge '+t.status+'">'+labels[t.status]+'</span></td><td><button class="link" data-detail="'+t.id+'">查看 →</button></td></tr>').join('')||'<tr><td colspan="6" class="empty">没有匹配任务</td></tr>'}
function modal(html){openDialog(html);labelFields($('#modal'))}
function detail(id){const t=tasks.find(t=>t.id===id);if(!t)return toast('任务不存在');modal('<div class="eyebrow">RUN TRACE / '+esc(id)+'</div><h2>'+esc(t.name||id)+'</h2><span class="badge '+t.status+'">'+labels[t.status]+'</span><div class="budget-panel"><div><small>累计成本</small><strong>¥'+t.cost.toFixed(2)+'</strong></div><div><small>子智能体</small><strong>'+t.childIds.length+'</strong></div><div><small>事件数量</small><strong>'+t.events.length+'</strong></div></div>'+t.alerts.map(a=>'<div class="note">'+esc(a.title)+' · '+esc(a.detail)+'<br>执行：'+acts[a.action]+'</div>').join('')+'<h3>调用轨迹</h3><div class="trace-scroll">'+(t.events.map(e=>'<div class="event"><time>'+new Date(e.at).toLocaleTimeString('zh-CN',{hour12:false})+'</time><div><strong>'+esc(e.agent||'root')+' → '+esc(e.tool||'spawn')+'</strong><p>'+esc(JSON.stringify(e.input||{}))+(e.error?' · 调用失败':'')+(e.childId?' · '+esc(e.childId):'')+'</p></div><span style="margin-left:auto">¥'+e.cost.toFixed(2)+'</span></div>').join('')||'<p>此条为初始样本。异常演练可查看逐步生成的事件轨迹。</p>')+'</div><div class="actions" style="margin-top:20px">'+(t.status==='approval'?'<button class="button primary" id="review">人工审批</button>':'')+(t.status==='running'?'<button class="button" id="finish">标记成功</button><button class="button" id="stop">停止任务</button>':'')+'</div>');$('#modal').dataset.task=t.id;if($('#review'))$('#review').onclick=()=>review(id);if($('#finish'))$('#finish').onclick=()=>change(t,'success');if($('#stop'))$('#stop').onclick=()=>change(t,'stopped')}
function change(t,s){t.status=s;if(activeTask===t&&s!=='running'){clearInterval(timer);timer=null;activeTask=null}persist();closeDialog();show();if(s==='running'&&t.simulation){t.simulation.recovery=3;run(t)}else nextRun()}
function review(id){const t=tasks.find(t=>t.id===id);if(!t)return toast('任务不存在');modal('<h2>审批 · '+esc(t.name||id)+'</h2><p>累计成本 ¥'+t.cost.toFixed(2)+'。批准后为本任务追加预算并恢复运行。</p><form id="approval"><label>追加预算（元）</label><input name="extra" type="number" value="5" min=".01" step=".01" required><div class="actions" style="margin-top:20px"><button class="button primary">批准并恢复</button><button type="button" class="button" id="reject">拒绝并停止</button></div></form>');$('#approval').onsubmit=e=>{e.preventDefault();if(t.status!=='approval')return toast('该任务已不在待审批状态');const extra=Number(new FormData(e.target).get('extra'));if(!Number.isFinite(extra)||extra<=0||extra>1000000)return toast('追加预算需大于 0 且不超过 1,000,000 元');t.budgetOverride=Math.max(t.cost,t.budgetOverride||policies[t.policy].budget)+extra;if(!t.simulation)t.simulation={scenario:'normal',step:0};change(t,'running');toast('已追加预算，检测规则继续生效')};$('#reject').onclick=()=>change(t,'stopped')}
function demo(){modal('<h2>异常演练</h2><p>每 0.8 秒生成一个事件，由引擎实时判断，不产生 API 费用。</p><form id="demo-form"><label>演练场景</label><select name="scenario"><option value="loop">循环调用 · 相同检索反复执行</option><option value="retry">异常重试 · 连续请求失败</option><option value="swarm">子智能体膨胀 · 持续创建新节点</option><option value="budget">预算触顶 · 累计成本达到上限</option><option value="normal">正常任务 · 成功完成</option></select><label>费用策略</label><select name="policy">'+Object.entries(policies).map(([k,p])=>'<option value="'+k+'">'+p.name+' / '+acts[p.action]+'</option>').join('')+'</select><label>客户名称</label><input name="customer" value="星河科技" maxlength="50" required><button class="button primary" style="margin-top:24px;width:100%">开始实时演练 →</button></form>');$('#demo-form').onsubmit=e=>{e.preventDefault();if(timer)return toast('请等待当前演练完成');const f=new FormData(e.target),s=f.get('scenario'),key=f.get('policy');if(!['loop','retry','swarm','budget','normal'].includes(s)||!Object.hasOwn(policies,key)||!String(f.get('customer')||'').trim())return toast('请选择有效场景、策略并填写客户名称');const t=task('AG-'+crypto.randomUUID().slice(0,8),key,{name:({loop:'循环检测演练',retry:'重试检测演练',swarm:'膨胀检测演练',budget:'预算控制演练',normal:'正常任务演练'})[s],customer:f.get('customer'),feature:presets[key].name});t.simulation={scenario:s,step:0};tasks.unshift(t);persist();closeDialog();location.hash='overview';show();run(t)}}
function run(t){
 if(timer){toast('已有演练运行中，本任务将随后继续');return}
 activeTask=t;
 timer=setInterval(()=>{
  if(t.status!=='running'){clearInterval(timer);timer=null;activeTask=null;nextRun();return}
  const sim=t.simulation,p={...policies[t.policy],budget:t.budgetOverride||policies[t.policy].budget},s=sim.scenario,i=++sim.step,recovery=sim.recovery>0;
  const e={id:t.id+'-'+i,agent:'root',tool:s==='swarm'&&!recovery?'spawn':'search_web',input:{query:s==='loop'&&!recovery?'2026 行业趋势':'步骤 '+i},cost:s==='budget'&&!recovery?p.budget/3+.01:.04,error:s==='retry'&&!recovery,...(s==='swarm'&&!recovery?{childId:'worker-'+i}:{})};
  const a=evaluate(t,e,p);
  if(a){toast(a.title+'：'+acts[a.action]);if(a.type==='budget'&&a.action==='degrade'){t.status='stopped';toast('预算已耗尽，已停止后续调用')}}
  if(recovery)sim.recovery--;
  if(t.status==='running'&&((s==='normal'&&i>=5)||(recovery&&sim.recovery===0)))t.status='success';
  if(t.status!=='running'){clearInterval(timer);timer=null;activeTask=null}
  persist();
  if(['overview','runs','cost','alerts'].includes(current)){const q=$('#search')?.value,st=$('#status')?.value,focus=document.activeElement?.id,pos=document.activeElement?.selectionStart;show();if(q!==undefined){$('#search').value=q;$('#status').value=st;$('#search').oninput();if(focus==='search'){$('#search').focus();if(typeof pos==='number')$('#search').setSelectionRange(pos,pos)}}}
  if($('#modal').open&&$('#modal').dataset.task===t.id)detail(t.id);
  if(!timer)nextRun();
 },800);
}
function nextRun(){const pending=tasks.find(t=>t.status==='running'&&t.simulation);if(pending)run(pending)}

function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({mode:'demo',policies,tasks},null,2)],{type:'application/json'}));a.download='agentguard-runs.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function labelFields(root){root.querySelectorAll('label').forEach((l,i)=>{const el=l.nextElementSibling;if(el&&['INPUT','SELECT'].includes(el.tagName)){if(!el.id)el.id=(root.id||'form')+'-field-'+i;l.htmlFor=el.id}})}
function bind(){if(current==='integrations')bindIntegrations();if(current==='coding')bindCoding();if(current==='usage')bindUsage();labelFields($('#app'));document.querySelectorAll('[data-check]').forEach(c=>{try{c.checked=localStorage.getItem('ag-check-'+c.dataset.check)==='1'}catch{}c.onchange=()=>{try{localStorage.setItem('ag-check-'+c.dataset.check,c.checked?'1':'0')}catch{toast('无法保存检查项，浏览器存储不可用')}}});document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=demo);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=download);document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-policy]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),p={...policies[f.dataset.policy]};['budget','loop','retries','children'].forEach(k=>p[k]=Number(d.get(k)));p.action=d.get('action');if(!validPolicy(p))return toast('请填写有效阈值：循环 2–12 次，其余上限为正整数');policies[f.dataset.policy]=p;if(persist())toast('策略已保存，将用于后续事件判断')});if($('#search')){const filter=()=>{const q=$('#search').value.toLowerCase(),s=$('#status').value;$('#rows').innerHTML=rows(tasks.filter(t=>(!s||s===t.status)&&[t.id,t.name,t.customer,t.feature].join(' ').toLowerCase().includes(q)));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))};$('#search').oninput=filter;$('#status').onchange=filter}}
window.addEventListener('hashchange',()=>{closeDialog();show()});document.querySelector('.skip-link').onclick=e=>{e.preventDefault();$('#app').focus()};show();nextRun();
